<script setup>
import {computed,onMounted,ref} from 'vue';
import {brewApi} from '../api';
import {pageMeta} from '../data';
import UserDirectory from './UserDirectory.vue';
import RoleBadge from './RoleBadge.vue';
defineProps({permissions:{type:Array,default:()=>[]}});
const accountContext=ref({});

    const tabs = [{ code: "users", label: "用户管理" }, { code: "roles", label: "角色管理" }, { code: "organizations", label: "组织机构" }];
    const menuOptions = Object.entries(pageMeta).map(([code, item]) => ({ code, label: item.title }));
    const allOrganizationTypes = [{ value: "company", label: "总部" }, { value: "factory", label: "厂区" }, { value: "department", label: "部门" }, { value: "workshop", label: "车间" }, { value: "team", label: "班组" }];
    const organizationTypes=computed(()=>allOrganizationTypes.filter(t=>accountContext.value.scope_kind==='headquarters'||!['company','factory'].includes(t.value)));
    const activeTab = ref("users"), loading = ref(false), saving = ref(false), error = ref(""), notice = ref(""), keyword = ref(""), editor = ref(""), editing = ref(null), draft = ref({});
    const users = ref([]), roleItems = ref([]), organizations = ref([]), factories = ref([]), suppliers = ref([]);
    const collapsedOrganizations = ref(new Set());
    const organizationPickerOpen = ref(false), pickerCollapsedOrganizations = ref(new Set());
    const activeRoles = computed(() => roleItems.value.filter(item => (item.active || draft.value.role_codes?.includes(item.code)) && (!accountContext.value.assignable_role_codes || accountContext.value.assignable_role_codes.includes(item.code))));
    const activeOrganizations = computed(() => organizations.value.filter(item => item.active || item.id === draft.value.organization_id || draft.value.organization_ids?.includes(String(item.id))));
    const selectedOrganization = computed(() => activeOrganizations.value.find(item => String(item.id) === String(draft.value.organization_id)) || null);
    const filteredUsers = computed(() => { const value = keyword.value.toLowerCase(); return users.value.filter(item => !value || [item.name,item.login,item.organization_name,item.job_title].some(field => String(field || '').toLowerCase().includes(value))); });
    const selectedFactories = computed(() => factories.value.filter(item => draft.value.factory_ids?.includes(String(item.id))));
    const organizationParentOptions = computed(() => { if(!editing.value) return organizations.value.filter(item=>item.active); const blocked=new Set([editing.value.id]); let changed=true; while(changed){ changed=false; organizations.value.forEach(item=>{ if(!blocked.has(item.id)&&blocked.has(item.parent_id)){ blocked.add(item.id); changed=true; } }); } return organizations.value.filter(item=>item.active&&!blocked.has(item.id)); });
    const organizationRows = computed(() => { const byParent = new Map(); organizations.value.forEach(item => { const key = String(organizations.value.some(o=>String(o.id)===String(item.parent_id)) ? item.parent_id : 'root'); if (!byParent.has(key)) byParent.set(key, []); byParent.get(key).push(item); }); const rows=[]; const visit=(parent,depth)=>{ (byParent.get(String(parent || 'root')) || []).sort((a,b)=>a.sequence-b.sequence||a.name.localeCompare(b.name,'zh-CN')).forEach(item=>{ const children=byParent.get(String(item.id))||[]; rows.push({...item,depth,hasChildren:children.length>0}); if(!collapsedOrganizations.value.has(item.id)) visit(item.id,depth+1); }); }; visit(null,0); return rows; });
    const organizationStats = computed(() => ({ total: organizations.value.length, factories: organizations.value.filter(item=>item.type==='factory').length, units: organizations.value.filter(item=>['department','workshop','team'].includes(item.type)).length, users: organizations.value.reduce((sum,item)=>sum+Number(item.user_count||0),0) }));
    const organizationPickerRows = computed(() => { const byParent = new Map(); activeOrganizations.value.forEach(item => { const key=String(activeOrganizations.value.some(o=>String(o.id)===String(item.parent_id)) ? item.parent_id : 'root'); if(!byParent.has(key)) byParent.set(key,[]); byParent.get(key).push(item); }); const rows=[]; const visit=(parent,depth)=>{ (byParent.get(String(parent||'root'))||[]).sort((a,b)=>a.sequence-b.sequence||a.name.localeCompare(b.name,'zh-CN')).forEach(item=>{ const children=byParent.get(String(item.id))||[]; rows.push({...item,depth,hasChildren:children.length>0}); if(!pickerCollapsedOrganizations.value.has(item.id)) visit(item.id,depth+1); }); }; visit(null,0); return rows; });
    function toggleOrganization(id){ const next=new Set(collapsedOrganizations.value); if(next.has(id)) next.delete(id); else next.add(id); collapsedOrganizations.value=next; }
    function openOrganizationPicker(){ const children=new Set(activeOrganizations.value.filter(item=>item.parent_id).map(item=>String(item.parent_id))); pickerCollapsedOrganizations.value=new Set(activeOrganizations.value.filter(item=>children.has(String(item.id))&&item.type!=='company').map(item=>item.id)); organizationPickerOpen.value=true; }
    function closeOrganizationPicker(){ organizationPickerOpen.value=false; }
    function togglePickerOrganization(id){ const next=new Set(pickerCollapsedOrganizations.value); if(next.has(id)) next.delete(id); else next.add(id); pickerCollapsedOrganizations.value=next; }
    function chooseOrganization(id){ draft.value.organization_id=String(id||''); closeOrganizationPicker(); }
    async function load() { loading.value=true; error.value=""; try {
      accountContext.value=await brewApi.getAdminContext();
      const allUsers=async()=>{const result=[];for(let page=1;;page++){const batch=await brewApi.listAdminUsers({page,page_size:100});result.push(...batch);if(batch.length<100)return result;}};
      [users.value,roleItems.value,organizations.value]=await Promise.all([allUsers(),brewApi.listAdminRoles(),brewApi.listAdminOrganizations()]);
      factories.value=accountContext.value.factories||[];
      suppliers.value=accountContext.value.can_configure_roles?await brewApi.listMaster('suppliers',{page_size:100,active:true}):[];
      const children=new Set(organizations.value.filter(item=>item.parent_id).map(item=>String(item.parent_id)));collapsedOrganizations.value=new Set(organizations.value.filter(item=>children.has(String(item.id))&&item.type!=='company').map(item=>item.id));
    } catch(cause){ error.value=cause.message||"账号配置加载失败。"; } finally { loading.value=false; } }
    function tabCount(code){ return code==='users'?users.value.length:code==='roles'?roleItems.value.length:organizations.value.length; }
    function roleName(code){ return roleItems.value.find(item=>item.code===code)?.label || code; }
    function closeEditor(){ editor.value=""; editing.value=null; draft.value={}; organizationPickerOpen.value=false; }
    function openUser(user=null,organizationId=""){ editing.value=user; draft.value=user?{...user,role_codes:[...(user.role_codes||[])],factory_ids:[...(user.factory_ids||[])],default_factory_id:user.default_factory_id||"",organization_id:user.organization_id||"",password:""}:{name:"",login:"",password:"",job_title:"",organization_id:organizationId||(accountContext.value.scope_kind==='factory'?organizations.value.find(o=>o.type==='factory')?.id||'':''),is_organization_manager:false,role_codes:[],factory_ids:[],default_factory_id:"",supplier_id:""}; editor.value='user'; error.value=""; }
    function openRole(role){ editing.value=role; draft.value={...role,name:role.label,menu_codes:[...(role.menu_codes||[])],organization_ids:[...(role.organization_ids||[])],direct_user_ids:[...(role.direct_user_ids||[])]}; editor.value='role'; error.value=""; }
    function openOrganization(item=null){ editing.value=item; draft.value=item?{...item,parent_id:item.parent_id||""}:{name:"",code:"",parent_id:accountContext.value.scope_kind==='factory'?organizations.value.find(o=>o.type==='factory')?.id||'':'',type:"department",address:"",active:true,sequence:10}; editor.value='organization'; error.value=""; }
    async function saveUser(){saving.value=true;error.value="";try{
      if(!draft.value.organization_id && !editing.value)throw Error('请选择账号所属的总部、厂区或部门。');
      const payload={name:draft.value.name,login:draft.value.login,organization_id:draft.value.organization_id||null,job_title:draft.value.job_title||"",is_organization_manager:!!draft.value.is_organization_manager,supplier_id:draft.value.supplier_id||null,role_codes:draft.value.role_codes};
      const factory=selectedOrganization.value?.factory_id;if(factory){payload.factory_ids=[String(factory)];payload.default_factory_id=factory;}
      if(editing.value)await brewApi.updateAdminUser(editing.value.id,{...payload,version:editing.value.version});else await brewApi.createAdminUser({...payload,password:draft.value.password});
      notice.value='用户配置已保存。';closeEditor();await load();
    }catch(cause){error.value=cause.message||'用户保存失败。';}finally{saving.value=false;}}
    async function saveRole(){ saving.value=true; error.value=""; try { await brewApi.updateAdminRole(draft.value.code,{name:draft.value.name,description:draft.value.description,active:draft.value.active,menu_codes:draft.value.menu_codes,organization_ids:draft.value.organization_ids,direct_user_ids:draft.value.direct_user_ids,version:editing.value.version}); notice.value="角色配置已保存，组织用户权限已同步。"; closeEditor(); await load(); } catch(cause){ error.value=cause.message||"角色保存失败。"; } finally { saving.value=false; } }
    async function saveOrganization(){ saving.value=true; error.value=""; try { const payload={name:draft.value.name,code:draft.value.code,parent_id:draft.value.parent_id||null,type:draft.value.type,address:draft.value.address||"",active:draft.value.active,sequence:draft.value.sequence||10}; if(editing.value) await brewApi.updateAdminOrganization(editing.value.id,{...payload,version:editing.value.version}); else await brewApi.createAdminOrganization(payload); notice.value="组织机构已保存。"; closeEditor(); await load(); } catch(cause){ error.value=cause.message||"组织保存失败。"; } finally { saving.value=false; } }
    async function toggleUser(user){ if(user.active && !window.confirm(`确定停用“${user.name}”吗？停用后其登录会话将失效。`)) return; try { await brewApi.adminUserAction(user.id,user.active?'disable':'enable',user.version); await load(); } catch(cause){ error.value=cause.message||"用户状态更新失败。"; } }
    async function resetPassword(user){ const password=window.prompt(`为“${user.name}”设置新密码（至少 8 位）`); if(!password) return; if(password.length<8){ error.value="新密码至少 8 位。"; return; } try { await brewApi.resetAdminUserPassword(user.id,{password}); notice.value="密码已重置，原登录会话已失效。"; } catch(cause){ error.value=cause.message||"密码重置失败。"; } }
    function organizationTypeLabel(type){ return allOrganizationTypes.find(item=>item.value===type)?.label||type; }
    function organizationTypeIcon(type){ return ({company:'总',factory:'厂',department:'部',workshop:'间',team:'组'})[type]||'组'; }
    onMounted(load);

</script>
<template>

    <div class="account-settings">
      <div class="account-tabs">
        <button v-for="tab in tabs" :key="tab.code" type="button" :class="{ active: activeTab === tab.code }" @click="activeTab = tab.code">{{ tab.label }}<small>{{ tabCount(tab.code) }}</small></button>
      </div>
      <div v-if="error" class="master-error">{{ error }}</div>
      <div v-if="notice" class="master-notice">{{ notice }}</div>

      <UserDirectory v-if="activeTab === 'users'" :users="users" :organizations="organizations" :factories="factories" :roles="roleItems" :context="accountContext" :loading="loading" @edit="openUser" @create="openUser(null,$event)" @refresh="load" @reset="resetPassword" @toggle="toggleUser" />
      <template v-else-if="activeTab === 'roles'">
        <div class="account-toolbar"><div><strong>角色管理</strong><span>角色使用系统权限模板，可配置名称、菜单、组织继承和直接用户</span></div><button class="btn btn-sm btn-secondary" type="button" @click="load">刷新</button></div>
        <div v-if="loading" class="empty">正在加载...</div>
        <div v-else class="role-card-grid"><article v-for="role in roleItems" :key="role.code" class="role-manage-card"><div class="role-card-head"><div class="role-card-icon">{{ role.label.slice(0,1) }}</div><div><RoleBadge :code="role.code" :label="role.label" /><small>{{ role.code }}</small></div><span :class="['master-state', role.active ? 'enabled' : 'muted']">{{ role.active ? '启用' : '停用' }}</span></div><p>{{ role.description || '系统内置权限模板' }}</p><div class="role-card-stats"><span><b>{{ role.menu_codes.length }}</b> 个菜单</span><span><b>{{ role.organization_ids.length }}</b> 个组织</span><span><b>{{ role.effective_user_count }}</b> 位用户</span></div><div class="account-tags"><span v-for="name in role.organization_names" :key="name" class="inherited">{{ name }}</span><i v-if="!role.organization_names.length">未配置组织继承</i></div><button class="btn btn-sm btn-outline role-configure" v-if="accountContext.can_configure_roles" type="button" @click="openRole(role)">配置角色</button></article></div>
      </template>

      <template v-else>
        <div class="account-toolbar"><div><strong>组织机构管理</strong><span>建立总部、厂区、部门、车间和班组层级；用户只能归属一个组织节点</span></div><div class="master-actions"><button class="btn btn-sm btn-secondary" type="button" @click="load">刷新</button><button v-if="accountContext.can_manage_organizations" class="btn btn-sm btn-primary" type="button" @click="openOrganization()">新增组织</button></div></div>
        <div class="organization-overview"><article><span>组织节点</span><strong>{{ organizationStats.total }}</strong><small>当前企业架构</small></article><article><span>厂区</span><strong>{{ organizationStats.factories }}</strong><small>生产地点</small></article><article><span>部门与车间</span><strong>{{ organizationStats.units }}</strong><small>业务组织单元</small></article><article><span>已归属用户</span><strong>{{ organizationStats.users }}</strong><small>按用户所属节点统计</small></article></div>
        <div v-if="loading" class="empty">正在加载...</div>
        <div v-else class="organization-list"><article v-for="item in organizationRows" :key="item.id" class="organization-row" :class="['org-type-' + item.type, { 'org-root': !item.parent_id }]" :style="{ '--org-depth': item.depth }"><div class="organization-tree-line"><button v-if="item.hasChildren" class="organization-toggle" type="button" :aria-label="collapsedOrganizations.has(item.id) ? '展开' : '折叠'" @click="toggleOrganization(item.id)">{{ collapsedOrganizations.has(item.id) ? '＋' : '−' }}</button><span v-else class="organization-toggle-placeholder"></span><span class="organization-type-icon">{{ organizationTypeIcon(item.type) }}</span></div><div class="organization-main"><div><strong>{{ item.name }}</strong><span :class="['master-state', item.active ? 'enabled' : 'muted']">{{ item.active ? '启用' : '停用' }}</span><span class="organization-kind">{{ organizationTypeLabel(item.type) }}</span></div></div><div class="organization-summary"><span class="organization-user-count"><b>{{ item.user_count }}</b> 位用户</span><span v-if="item.role_names.length" class="organization-role-tags"><i v-for="role in item.role_names" :key="role">{{ role }}</i></span></div><button v-if="accountContext.can_manage_organizations && (accountContext.scope_kind==='headquarters' || !['company','factory'].includes(item.type))" class="btn btn-xs btn-outline" type="button" @click="openOrganization(item)">编辑</button></article></div>
      </template>

      <form v-if="editor === 'user'" class="equipment-modal-mask" @submit.prevent="saveUser"><div class="equipment-modal account-editor-modal"><div class="equipment-modal-header"><div><div class="modal-title">{{ editing ? '编辑用户' : '新增用户' }}</div><div class="modal-subtitle">基础信息、组织归属、角色和厂区范围集中配置</div></div><button class="equipment-close" type="button" @click="closeEditor">×</button></div><div class="account-editor-body"><div v-if="error" class="master-error" role="alert">{{ error }}</div><section><h3>账号信息</h3><div class="account-form-grid"><label><span><i>*</i>姓名</span><input v-model.trim="draft.name" required></label><label><span><i>*</i>登录账号</span><input v-model.trim="draft.login" required></label><label v-if="!editing"><span><i>*</i>初始密码</span><input v-model="draft.password" type="password" minlength="8" required></label><label><span>岗位</span><input v-model.trim="draft.job_title" placeholder="如：糖化操作工"></label></div></section><section><h3>组织归属</h3><div class="account-form-grid"><label><span>所属组织</span><button class="org-picker-trigger" type="button" @click="openOrganizationPicker"><span>{{ selectedOrganization?.path || '暂不分配' }}</span><b>选择组织⌄</b></button></label><label class="account-check-line"><input v-model="draft.is_organization_manager" type="checkbox"><span>设为该组织负责人（酒厂负责人自动获得本厂业务查看权限）</span></label></div></section><section><h3>直接角色 <small>组织继承的角色会自动叠加</small></h3><div class="permission-check-grid"><label v-for="role in activeRoles" :key="role.code"><input v-model="draft.role_codes" type="checkbox" :value="role.code"><span><strong>{{ role.label }}</strong><small>{{ role.description || role.code }}</small></span></label></div></section><section><h3>数据范围</h3><p class="account-scope-hint">{{ selectedOrganization?.factory_id ? '仅 '+(factories.find(f=>String(f.id)===String(selectedOrganization.factory_id))?.name||'所属厂区')+' · 由组织归属确定' : selectedOrganization ? '总部 · 全部厂区，操作权限由岗位角色确定' : '请先选择组织。历史账号原授权在明确组织归属前保留。' }}</p></section><section v-if="draft.role_codes.includes('supplier')"><h3>供应商账号</h3><label><span><i>*</i>关联供应商</span><select v-model="draft.supplier_id" required><option value="">请选择供应商</option><option v-for="supplier in suppliers" :key="supplier.id" :value="supplier.id">{{ supplier.name }}</option></select></label></section></div><div class="equipment-modal-footer"><button class="btn btn-secondary" type="button" @click="closeEditor">取消</button><button class="btn btn-primary" type="submit" :disabled="saving">{{ saving ? '保存中...' : '保存用户' }}</button></div></div>
        <div v-if="organizationPickerOpen" class="org-picker-mask" @click.self="closeOrganizationPicker"><section class="org-picker-modal" role="dialog" aria-modal="true" aria-label="选择所属组织"><header class="org-picker-header"><div><strong>选择所属组织</strong><small>展开厂区查看部门、车间和班组</small></div><button type="button" class="equipment-close" @click="closeOrganizationPicker">×</button></header><div class="org-picker-current"><small>当前选择</small><strong>{{ selectedOrganization?.path || '暂不分配' }}</strong></div><div class="org-picker-tree"><button v-if="accountContext.scope_kind==='headquarters' && editing" type="button" class="org-picker-none" :class="{ selected: !draft.organization_id }" @click="chooseOrganization('')">暂不分配组织</button><div v-for="item in organizationPickerRows" :key="item.id" class="org-picker-row" :style="{ '--picker-depth': item.depth }"><button v-if="item.hasChildren" type="button" class="org-picker-toggle" :aria-label="pickerCollapsedOrganizations.has(item.id) ? '展开' : '折叠'" @click="togglePickerOrganization(item.id)">{{ pickerCollapsedOrganizations.has(item.id) ? '＋' : '−' }}</button><span v-else class="org-picker-toggle-placeholder"></span><button type="button" class="org-picker-node" :class="{ selected: String(draft.organization_id) === String(item.id) }" @click="chooseOrganization(item.id)"><span class="organization-type-icon">{{ organizationTypeIcon(item.type) }}</span><span><strong>{{ item.name }}</strong><small>{{ organizationTypeLabel(item.type) }} · {{ item.code }}</small></span><b v-if="String(draft.organization_id) === String(item.id)">已选</b></button></div></div><footer class="org-picker-footer"><button type="button" class="btn btn-secondary" @click="closeOrganizationPicker">取消</button></footer></section></div></form>

      <form v-if="editor === 'role'" class="equipment-modal-mask" @submit.prevent="saveRole"><div class="equipment-modal account-editor-modal"><div class="equipment-modal-header"><div><div class="modal-title">配置角色 · {{ draft.name }}</div><div class="modal-subtitle">{{ draft.code }} · 权限模板固定，菜单和适用范围可配置</div></div><button class="equipment-close" type="button" @click="closeEditor">×</button></div><div class="account-editor-body"><div v-if="error" class="master-error" role="alert">{{ error }}</div><section><h3>基本信息</h3><div class="account-form-grid"><label><span><i>*</i>角色名称</span><input v-model.trim="draft.name" required></label><label class="account-check-line"><input v-model="draft.active" type="checkbox"><span>启用该角色</span></label><label class="account-wide"><span>角色说明</span><textarea v-model.trim="draft.description" rows="2"></textarea></label></div></section><section><h3>菜单权限</h3><div class="permission-check-grid"><label v-for="menu in menuOptions" :key="menu.code"><input v-model="draft.menu_codes" type="checkbox" :value="menu.code"><span><strong>{{ menu.label }}</strong><small>{{ menu.code }}</small></span></label></div></section><section><h3>适用组织 <small>选择后，该组织及其下级组织用户自动继承此角色</small></h3><div class="permission-check-grid"><label v-for="item in activeOrganizations" :key="item.id"><input v-model="draft.organization_ids" type="checkbox" :value="String(item.id)"><span><strong>{{ item.name }}</strong><small>{{ item.path }}</small></span></label></div></section><section><h3>直接用户 <small>适合跨组织兼职或特殊授权</small></h3><div class="permission-check-grid"><label v-for="user in users" :key="user.id"><input v-model="draft.direct_user_ids" type="checkbox" :value="String(user.id)"><span><strong>{{ user.name }}</strong><small>{{ user.organization_name || user.login }}</small></span></label></div></section></div><div class="equipment-modal-footer"><button class="btn btn-secondary" type="button" @click="closeEditor">取消</button><button class="btn btn-primary" type="submit" :disabled="saving">{{ saving ? '保存中...' : '保存角色配置' }}</button></div></div></form>

      <form v-if="editor === 'organization'" class="equipment-modal-mask" @submit.prevent="saveOrganization"><div class="equipment-modal material-category-modal"><div class="equipment-modal-header"><div><div class="modal-title">{{ editing ? '编辑组织' : '新增组织' }}</div><div class="modal-subtitle">维护组织层级和基础信息</div></div><button class="equipment-close" type="button" @click="closeEditor">×</button></div><div class="equipment-modal-body material-category-form"><label><span><i>*</i>组织名称</span><input v-model.trim="draft.name" required></label><label><span><i>*</i>组织编码</span><input v-model.trim="draft.code" required></label><label><span>上级组织</span><select v-model="draft.parent_id"><option value="">无上级组织</option><option v-for="item in organizationParentOptions" :key="item.id" :value="item.id">{{ item.path }}</option></select></label><label><span><i>*</i>组织类型</span><select v-model="draft.type" required><option v-for="type in organizationTypes" :key="type.value" :value="type.value">{{ type.label }}</option></select></label><label><span>地址</span><input v-model.trim="draft.address"></label><label v-if="editing" class="account-check-line"><input v-model="draft.active" type="checkbox"><span>启用该组织</span></label></div><div class="equipment-modal-footer"><button class="btn btn-secondary" type="button" @click="closeEditor">取消</button><button class="btn btn-primary" type="submit" :disabled="saving">{{ saving ? '保存中...' : '保存组织' }}</button></div></div></form>
    </div>
</template>
<style scoped>
.account-scope-hint{font-size:12px;color:var(--text-secondary);line-height:1.8;margin:0}.account-tabs button{font-size:13px;padding:14px 20px}.account-tabs small{font-size:10px}.account-toolbar{padding:18px 20px}.account-toolbar>div>span{font-size:11px}.organization-overview{display:none}
</style>
